mapper.select:
SELECT COUNT(*)
FROM mes_pro_task
WHERE deleted = 0
  AND start_time >= #{beginTime}
  AND start_time < #{endTime}

SELECT IFNULL(SUM(quantity), 0)
FROM mes_pro_task
WHERE deleted = 0
  AND start_time >= #{beginTime}
  AND start_time < #{endTime}

SELECT COUNT(*)
FROM mes_pro_feedback
WHERE deleted = 0
  AND feedback_time >= #{beginTime}
  AND feedback_time < #{endTime}

SELECT IFNULL(SUM(feedback_quantity), 0)
FROM mes_pro_feedback
WHERE deleted = 0
  AND feedback_time >= #{beginTime}
  AND feedback_time < #{endTime}
